"""Opt-in original boundary counts for an ordinary corner-pattern recipe.

Reserving extra common rows resamples every curved side, even when all internal
station-movement checks pass. Keep the original analytic common count, and
compare against that original sampled boundary. This retains the existing
station proposals, complete error bounds, profile pins and surface guards.

This experiment is not yet part of a published recipe. Original count changes
at genuine geometric thresholds remain discrete and need editing validation.
"""
from . import curved_multisided_quad_nodes as cyclic
from .curved_contact_mesh_station_nodes import counts
from .curved_quad_fair_nodes import assign_group


def replace_saved(root):
    """Copy ordinary recipe paths; leave original fallbacks and other families."""
    memo={};changed=[]
    def visit(tree,ordinary=False):
        ordinary=ordinary or tree.get('st_corner_pattern_family')=='ordinary'
        if tree.get('st_corner_pattern_family')=='multi_site':ordinary=False
        key=(tree.as_pointer(),ordinary)
        if key in memo:return memo[key]
        if (ordinary and 'Original counts with contact mesh knots v1' in tree.name and
                'Reserved contact primitive' in tree.name):
            result=counts(cyclic.plan(compound=False,continuations=True))
            changed.append(dict(kind='original_counts',group=tree.name))
            memo[key]=result
            return result
        children=[(n.name,visit(n.node_tree,ordinary)) for n in tree.nodes if n.type=='GROUP' and n.node_tree]
        replacements=[(name,child) for name,child in children if child!=tree.nodes[name].node_tree]
        bound=ordinary and tree.name.startswith('Prochitecture Streets / Mesh boundary preservation v1') and 'Reserved contact primitive' in tree.name
        result=tree.copy() if replacements or bound else tree
        for name,child in replacements:assign_group(result.nodes[name],child)
        if bound:
            matches=[n for n in result.nodes if n.type=='GROUP' and 'Depths' in n.inputs and
                     n.inputs['Depths'].is_linked and n.inputs['Depths'].links[0].from_node.type=='GROUP_INPUT' and
                     n.inputs['Depths'].links[0].from_socket.name=='Depths' and 'Side Count' in n.outputs]
            if len(matches)!=1:raise ValueError(('Expected one original boundary plan',tree.name,len(matches)))
            assign_group(matches[0],cyclic.plan(compound=False,continuations=True))
            result.name='Original-count boundary comparison / '+tree.name
            changed.append(dict(kind='original_boundary_count',group=tree.name))
        memo[key]=result
        return result
    result=visit(root)
    if {row['kind'] for row in changed}!={'original_counts','original_boundary_count'}:
        raise ValueError(('Incomplete original-count replacement',changed))
    return result,changed
